// Рассчитываем период: с 1 января до вчерашнего дня
const now = new Date();
const yesterday = new Date(now);
yesterday.setDate(yesterday.getDate() - 1);
yesterday.setHours(23, 59, 59, 999);

const periodStart = '2026-01-01';
const periodEnd = yesterday.toISOString().split('T')[0];

console.log(`📅 Период: ${periodStart} - ${periodEnd}`);

return {
  json: {
    period_start: periodStart,
    period_end: periodEnd,
    period_end_full: yesterday.toISOString()
  }
};

// Формируем правильный URL для Supabase
const periodData = $input.first().json;
const periodStart = periodData.period_start;
const periodEndFull = periodData.period_end_full;

// Supabase требует формат: posted_at=gte.2026-01-01&posted_at=lte.2026-01-22T23:59:59.999Z
const url = `https://pyscczcuersdjvpmkiec.supabase.co/rest/v1/instagram_posts_stats?posted_at=gte.${periodStart}&posted_at=lte.${periodEndFull}&order=posted_at.asc`;

console.log(`🔗 URL: ${url}`);

return {
  json: {
    url: url,
    period_start: periodStart,
    period_end: periodData.period_end,
    period_end_full: periodEndFull
  }
};

// Получаем период из предыдущего узла
const periodData = $('📅 Calculate Period').first().json;
const periodStart = periodData.period_start;
const periodEnd = periodData.period_end;

// Получаем посты из Supabase
// Supabase возвращает массив напрямую
const input = $input.first().json;

console.log('🔍 Input type:', typeof input);
console.log('🔍 Is array:', Array.isArray(input));
console.log('🔍 Input:', JSON.stringify(input).substring(0, 200));

// Проверяем, что это массив
let posts = [];
if (Array.isArray(input)) {
  posts = input;
} else if (input && Array.isArray(input.data)) {
  posts = input.data;
} else if (input && typeof input === 'object') {
  // Может быть один объект
  posts = [input];
} else {
  console.log('⚠️ Нет данных от Supabase или неправильный формат');
  console.log('Input:', input);
  return { json: { skip: true, reason: 'no_data', input_type: typeof input } };
}

console.log(`📊 Получено постов за период ${periodStart} - ${periodEnd}: ${posts.length}`);

if (posts.length === 0) {
  console.log('⚠️ Нет постов за этот период');
  return { json: { skip: true, reason: 'no_posts' } };
}

// Считаем метрики
const stories = posts.filter(p => {
  const mediaType = (p.media_type || '').toLowerCase();
  return mediaType.includes('story') || mediaType === 'stories';
}).length;

const publications = posts.filter(p => {
  const mediaType = (p.media_type || '').toLowerCase();
  return !mediaType.includes('story') && mediaType !== 'stories';
}).length;

// Суммируем метрики
const totalReach = posts.reduce((sum, p) => sum + (p.reach || 0), 0);
const totalImpressions = posts.reduce((sum, p) => sum + (p.impressions || 0), 0);
const totalLikes = posts.reduce((sum, p) => sum + (p.likes || 0), 0);
const totalComments = posts.reduce((sum, p) => sum + (p.comments || 0), 0);
const totalShares = posts.reduce((sum, p) => sum + (p.shares || 0), 0);

// Вовлеченность = (лайки + комментарии + репосты) / показы * 100
const engagement = totalImpressions > 0 
  ? ((totalLikes + totalComments + totalShares) / totalImpressions) * 100 
  : 0;

// Бизнес-метрики
const totalDiagnostics = posts.reduce((sum, p) => sum + (p.leads_count || 0), 0);
const totalSales = posts.reduce((sum, p) => sum + (p.paid_leads || 0), 0);
const totalRevenue = posts.reduce((sum, p) => sum + (p.revenue || 0), 0);

const projectId = '64c94e87-630c-470e-8ab1-8f7c8c835efa';

const result = {
  project_id: projectId,
  period_start: periodStart,
  period_end: periodEnd,
  publications: publications,
  stories: stories,
  reach: totalReach,
  engagement: Math.round(engagement * 100) / 100, // 2 знака после запятой
  followers: 0, // TODO: получить из Instagram Insights API
  diagnostics: totalDiagnostics,
  sales: totalSales,
  revenue: Math.round(totalRevenue), // БЕЗ КОПЕЕК
};

console.log(`\n✅ Агрегированные метрики за ${periodStart} - ${periodEnd}:`);
console.log(`   Публикации: ${publications}`);
console.log(`   Сторис: ${stories}`);
console.log(`   Охват: ${totalReach.toLocaleString('ru-RU')}`);
console.log(`   Вовлеченность: ${result.engagement}%`);
console.log(`   Диагностики: ${totalDiagnostics}`);
console.log(`   Продажи: ${totalSales}`);
console.log(`   Выручка: ${totalRevenue.toLocaleString('ru-RU')}₸`);

return { json: result };

const result = $input.first().json;

console.log(`\n✅ УСПЕШНО СОХРАНЕНО в content_production_stats!\n`);
console.log(`   Период: ${result.period_start} - ${result.period_end}`);
console.log(`   Публикации: ${result.publications}`);
console.log(`   Сторис: ${result.stories}`);
console.log(`   Охват: ${result.reach.toLocaleString('ru-RU')}`);
console.log(`   Вовлеченность: ${result.engagement}%`);

return {
  json: {
    success: true,
    message: `Статистика за ${result.period_start} - ${result.period_end} успешно сохранена`,
    timestamp: new Date().toISOString()
  }
};
